package com.elialombardi.piccistodo.auth

/*
 * Security model: the P-256 private key never leaves Android Keystore and each
 * signing operation requires BIOMETRIC_STRONG authorization via CryptoObject.
 * Password JWTs are used only for registration; access JWTs live only in RAM.
 * The server must issue single-use, device-bound challenges expiring in 60s and
 * consume them atomically on verification. Process death discards pending work;
 * retry starts a new operation. Local checks do not replace server enforcement.
 */

import android.os.Build
import android.os.SystemClock
import android.security.keystore.KeyPermanentlyInvalidatedException
import android.util.Base64
import android.util.Log
import androidx.fragment.app.FragmentActivity
import com.elialombardi.piccistodo.BuildConfig
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import java.security.GeneralSecurityException
import java.time.Instant
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BiometricLoginUseCase @Inject constructor(
    private val keys: KeyManager,
    private val biometrics: BiometricAuthenticator,
    private val repository: AuthRepository,
    private val deviceIds: DeviceIdProvider
) {
    private val operation = Mutex()

    suspend fun hasKey(): Boolean = withContext(Dispatchers.IO) { keys.hasKey(KEY_ALIAS) }

    suspend fun enrollDevice(passwordJwt: String) = operation.withLock {
        withContext(Dispatchers.IO) {
            try {
                if (keys.hasKey(KEY_ALIAS)) {
                    try { keys.prepareSignature(KEY_ALIAS) }
                    catch (_: KeyPermanentlyInvalidatedException) { keys.deleteKey(KEY_ALIAS) }
                }
                if (!keys.hasKey(KEY_ALIAS)) keys.generateKeyPair(KEY_ALIAS)
                repository.registerDevice(
                    passwordJwt, deviceIds.getDeviceId(), keys.getPublicKeyPem(KEY_ALIAS),
                    "${Build.MANUFACTURER} ${Build.MODEL}"
                )
            } catch (_: GeneralSecurityException) { throw AuthError.KeyUnavailable() }
            // No field/coroutine state retains passwordJwt after return. JVM Strings
            // cannot be reliably zeroized; the caller must also drop its reference.
        }
    }

    suspend fun login(activity: FragmentActivity): String = operation.withLock {
        val signature = withContext(Dispatchers.IO) {
            try { keys.prepareSignature(KEY_ALIAS) }
            catch (_: GeneralSecurityException) { throw AuthError.KeyUnavailable() }
        }
        // Authorize this exact operation BEFORE network so failed/canceled biometrics
        // make zero HTTP requests. initSign AFTER the prompt would lose authorization.
        val authenticated = biometrics.authenticate(activity, biometrics.promptInfo(), signature)
        currentCoroutineContext().ensureActive()
        val deviceId = withContext(Dispatchers.IO) { deviceIds.getDeviceId() }
        val requestedAt = SystemClock.elapsedRealtime()
        val challenge = repository.requestChallenge(deviceId)
        val bytes = validateChallenge(challenge, requestedAt)
        try {
            val encoded = withContext(Dispatchers.IO) {
                try { Base64.encodeToString(keys.sign(KEY_ALIAS, bytes, authenticated), Base64.NO_WRAP) }
                catch (_: GeneralSecurityException) { throw AuthError.KeyUnavailable() }
            }
            if (BuildConfig.DEBUG) Log.d("BiometricLogin", "DER signature (base64): $encoded")
            currentCoroutineContext().ensureActive()
            validateChallenge(challenge, requestedAt)
            val response = repository.verifyChallenge(deviceId, encoded)
            currentCoroutineContext().ensureActive()
            val token = response.accessToken ?: throw AuthError.InvalidResponse()
            TokenHolder.set(token, response.expiresIn)
            token
        } finally { bytes.fill(0) }
    }

    private fun validateChallenge(response: ChallengeResponse, requestedAt: Long): ByteArray {
        val challenge = response.challenge?.takeIf { it.isNotBlank() && it.length <= 8192 }
            ?: throw AuthError.InvalidResponse()
        val value = response.expiresAt ?: throw AuthError.InvalidResponse()
        val expiry = runCatching { Instant.parse(value) }.getOrElse {
            value.toLongOrNull()?.let(Instant::ofEpochSecond) ?: throw AuthError.InvalidResponse()
        }
        if (!expiry.isAfter(Instant.now()) || SystemClock.elapsedRealtime() - requestedAt >= 60_000) {
            throw AuthError.ChallengeExpired()
        }
        val decoded = try {
            Base64.decode(
                challenge,
                Base64.URL_SAFE or Base64.NO_PADDING or Base64.NO_WRAP
            )
        } catch (_: IllegalArgumentException) {
            throw AuthError.InvalidResponse()
        }
        if (decoded.size != 32) throw AuthError.InvalidResponse()
        return decoded
    }

    companion object { const val KEY_ALIAS = "piccis_biometric_signing_v1" }
}

package com.elialombardi.piccistodo.auth

/*
 * Security model: the P-256 private key never leaves Android Keystore and each
 * signing operation requires BIOMETRIC_STRONG authorization via CryptoObject.
 * Password JWTs are used only for registration; access JWTs live only in RAM.
 * The server must issue single-use, device-bound challenges expiring in 60s and
 * consume them atomically on verification. Process death discards pending work;
 * retry starts a new operation. Local checks do not replace server enforcement.
 */

import android.os.Build
import android.os.SystemClock
import android.security.keystore.KeyPermanentlyInvalidatedException
import android.util.Base64
import android.util.Log
import androidx.fragment.app.FragmentActivity
import com.elialombardi.piccistodo.BuildConfig
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import java.security.GeneralSecurityException
import java.time.Instant
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BiometricLoginUseCase @Inject constructor(
    private val keys: KeyManager,
    private val biometrics: BiometricAuthenticator,
    private val repository: AuthRepository,
    private val deviceIds: DeviceIdProvider
) {
    private val operation = Mutex()

    suspend fun hasKey(): Boolean = withContext(Dispatchers.IO) { keys.hasKey(KEY_ALIAS) }

    suspend fun enrollDevice(passwordJwt: String) = operation.withLock {
        withContext(Dispatchers.IO) {
            try {
                if (keys.hasKey(KEY_ALIAS)) {
                    try { keys.prepareSignature(KEY_ALIAS) }
                    catch (_: KeyPermanentlyInvalidatedException) { keys.deleteKey(KEY_ALIAS) }
                }
                if (!keys.hasKey(KEY_ALIAS)) keys.generateKeyPair(KEY_ALIAS)
                repository.registerDevice(
                    passwordJwt, deviceIds.getDeviceId(), keys.getPublicKeyPem(KEY_ALIAS),
                    "${Build.MANUFACTURER} ${Build.MODEL}"
                )
            } catch (_: GeneralSecurityException) { throw AuthError.KeyUnavailable() }
            // No field/coroutine state retains passwordJwt after return. JVM Strings
            // cannot be reliably zeroized; the caller must also drop its reference.
        }
    }

    suspend fun login(activity: FragmentActivity): String = operation.withLock {
        val signature = withContext(Dispatchers.IO) {
            try { keys.prepareSignature(KEY_ALIAS) }
            catch (_: GeneralSecurityException) { throw AuthError.KeyUnavailable() }
        }
        // Authorize this exact operation BEFORE network so failed/canceled biometrics
        // make zero HTTP requests. initSign AFTER the prompt would lose authorization.
        val authenticated = biometrics.authenticate(activity, biometrics.promptInfo(), signature)
        currentCoroutineContext().ensureActive()
        val deviceId = withContext(Dispatchers.IO) { deviceIds.getDeviceId() }
        val requestedAt = SystemClock.elapsedRealtime()
        val challenge = repository.requestChallenge(deviceId)
        val bytes = validateChallenge(challenge, requestedAt)
        try {
            val encoded = withContext(Dispatchers.IO) {
                try { Base64.encodeToString(keys.sign(KEY_ALIAS, bytes, authenticated), Base64.NO_WRAP) }
                catch (_: GeneralSecurityException) { throw AuthError.KeyUnavailable() }
            }
            currentCoroutineContext().ensureActive()
            validateChallenge(challenge, requestedAt)
            val response = repository.verifyChallenge(deviceId, encoded)
            currentCoroutineContext().ensureActive()
            val token = response.accessToken ?: throw AuthError.InvalidResponse()
            TokenHolder.set(token, response.expiresIn, response.role)
            if (BuildConfig.DEBUG) {
                val role = TokenHolder.session.value?.role
                    ?.replace('\r', ' ')?.replace('\n', ' ')?.take(64) ?: "unknown"
                Log.d("BiometricLogin", "Login successful; user role: $role")
            }
            token
        } finally { bytes.fill(0) }
    }

    private fun validateChallenge(response: ChallengeResponse, requestedAt: Long): ByteArray {
        val challenge = response.challenge?.takeIf { it.isNotBlank() && it.length <= 8192 }
            ?: throw AuthError.InvalidResponse()
        val value = response.expiresAt ?: throw AuthError.InvalidResponse()
        val expiry = runCatching { Instant.parse(value) }.getOrElse {
            value.toLongOrNull()?.let(Instant::ofEpochSecond) ?: throw AuthError.InvalidResponse()
        }
        if (!expiry.isAfter(Instant.now()) || SystemClock.elapsedRealtime() - requestedAt >= 60_000) {
            throw AuthError.ChallengeExpired()
        }
        val decoded = try {
            Base64.decode(
                challenge,
                Base64.URL_SAFE or Base64.NO_PADDING or Base64.NO_WRAP
            )
        } catch (_: IllegalArgumentException) {
            throw AuthError.InvalidResponse()
        }
        if (decoded.size != 32) throw AuthError.InvalidResponse()
        return decoded
    }

    companion object { const val KEY_ALIAS = "piccis_biometric_signing_v1" }
}

package com.elialombardi.piccistodo.auth

import android.os.SystemClock
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/** Process-local only. Nothing here is saved to preferences, saved state, disk or backups. */
object TokenHolder {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)
    private var expiryJob: Job? = null
    private val _signedIn = MutableStateFlow(false)
    val signedIn = _signedIn.asStateFlow()

    @Volatile private var token: String? = null
    @Volatile var expiresAt: Long = 0L // elapsedRealtime, unaffected by clock changes
        private set

    val accessToken: String?
        @Synchronized get() {
            if (token != null && SystemClock.elapsedRealtime() >= expiresAt) clear()
            return token
        }

    @Synchronized
    fun set(accessToken: String, expiresIn: Long) {
        require(accessToken.isNotBlank() && expiresIn in 1..31_536_000)
        clear()
        token = accessToken
        expiresAt = SystemClock.elapsedRealtime() + expiresIn * 1000
        _signedIn.value = true
        expiryJob = scope.launch {
            delay(expiresIn * 1000)
            // Read via the getter to avoid clearing a newer session.
            this@TokenHolder.accessToken
        }
    }

    @Synchronized
    fun clearRejected(rejected: String) {
        if (token == rejected) clear()
    }

    @Synchronized
    fun clear() {
        expiryJob?.cancel()
        expiryJob = null
        token = null
        expiresAt = 0L
        _signedIn.value = false
    }
}

package com.elialombardi.piccistodo.auth

import android.os.SystemClock
import android.util.Base64
import org.json.JSONObject
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/** Process-local only. Nothing here is saved to preferences, saved state, disk or backups. */
object TokenHolder {
    // Not a data class: generated toString() must not expose bearer credentials.
    class Session(val accessToken: String, val role: String?)
    private val _session = MutableStateFlow<Session?>(null)
    val session = _session.asStateFlow()
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)
    private var expiryJob: Job? = null
    private val _signedIn = MutableStateFlow(false)
    val signedIn = _signedIn.asStateFlow()

    @Volatile private var token: String? = null
    @Volatile var expiresAt: Long = 0L // elapsedRealtime, unaffected by clock changes
        private set

    val accessToken: String?
        @Synchronized get() {
            if (token != null && SystemClock.elapsedRealtime() >= expiresAt) clear()
            return token
        }

    @Synchronized
    fun set(accessToken: String, expiresIn: Long, role: String? = null) {
        require(accessToken.isNotBlank() && expiresIn in 1..31_536_000)
        clear()
        token = accessToken
        expiresAt = SystemClock.elapsedRealtime() + expiresIn * 1000
        _session.value = Session(accessToken, role?.takeIf { it.isNotBlank() } ?: tokenRole(accessToken))
        _signedIn.value = true
        expiryJob = scope.launch {
            delay(expiresIn * 1000)
            // Read via the getter to avoid clearing a newer session.
            this@TokenHolder.accessToken
        }
    }

    // UI hint only, not signature verification or authorization; the API enforces access.
    private fun tokenRole(accessToken: String): String? = runCatching {
        val parts = accessToken.split('.')
        if (parts.size != 3) return@runCatching null
        val payload = String(Base64.decode(parts[1], Base64.URL_SAFE or Base64.NO_WRAP), Charsets.UTF_8)
        JSONObject(payload).opt("role") as? String
    }.getOrNull()?.takeIf { it.isNotBlank() }

    @Synchronized
    fun clearRejected(rejected: String) {
        if (token == rejected) clear()
    }

    @Synchronized
    fun clear() {
        expiryJob?.cancel()
        expiryJob = null
        token = null
        expiresAt = 0L
        _session.value = null
        _signedIn.value = false
    }
}

package com.elialombardi.piccistodo.data.local

import android.content.Context
import androidx.datastore.preferences.core.booleanPreferencesKey
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import com.elialombardi.piccistodo.BuildConfig
import com.elialombardi.piccistodo.auth.TokenHolder
import com.elialombardi.piccistodo.auth.ServerUrl
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import okhttp3.HttpUrl
import javax.inject.Inject
import javax.inject.Singleton

private val Context.dataStore by preferencesDataStore(name = "user_prefs")

data class LoginSession(val hasToken: Boolean, val usable: Boolean, val biometricEnabled: Boolean)

@Singleton
class SettingsManager @Inject constructor(private val context: Context) {

    // 1. Keys
    private val tokenKey = stringPreferencesKey("jwt_token")
    private val roleKey = stringPreferencesKey("session_role")
    private val apiUrlKey = stringPreferencesKey("api_url")
    private val biometricEnabledKey = booleanPreferencesKey("biometric_enabled")
    private val urlMutex = Mutex()
    @Volatile private var cachedApiUrl: String? = null

    // Migration deletes legacy encrypted/plaintext JWTs without ever loading them.
    init {
        CoroutineScope(SupervisorJob() + Dispatchers.IO).launch {
            context.dataStore.edit { it.remove(tokenKey); it.remove(roleKey) }
            getApiUrl()
        }
    }

    // 3. Flows for the UI
    val apiUrlFlow: Flow<String> = context.dataStore.data.map {
        it[apiUrlKey]?.let(ServerUrl::normalize) ?: BuildConfig.BASE_URL
    }
    val sessionFlow = combine(TokenHolder.signedIn, apiUrlFlow) { _, url ->
        Triple(TokenHolder.accessToken, url, null as String?)
    }

    val biometricEnabledFlow: Flow<Boolean> = context.dataStore.data
        .map { it[biometricEnabledKey] ?: false }

    val loginSessionFlow: Flow<LoginSession> = combine(TokenHolder.signedIn, biometricEnabledFlow) { _, enabled ->
        val usable = TokenHolder.accessToken != null
        LoginSession(usable, usable, enabled)
    }

    // 4. Sync getters (same pattern as getTokenSync / getApiUrlSync)
    fun getTokenSync(): String? {
        return TokenHolder.accessToken
    }

    // Login awaits getApiUrl/saveApiUrl before any authenticated client is used.
    fun getApiUrlSync(): String = cachedApiUrl ?: BuildConfig.BASE_URL

    suspend fun getApiUrl(): String = withContext(Dispatchers.IO) {
        urlMutex.withLock {
            cachedApiUrl ?: apiUrlFlow.first().also { cachedApiUrl = it }
        }
    }

    @Synchronized
    fun getTokenForUrl(url: HttpUrl): String? =
        if (ServerUrl.origin(url) == getApiUrlSync()) TokenHolder.accessToken else null

    fun hasStoredToken(): Boolean = getTokenSync()?.isNotBlank() == true

    suspend fun saveApiUrl(url: String) {
        val normalized = requireNotNull(ServerUrl.normalize(url)) { ServerUrl.validationMessage }
        withContext(Dispatchers.IO) {
            urlMutex.withLock {
                val previous = cachedApiUrl ?: apiUrlFlow.first()
                context.dataStore.edit { prefs -> prefs[apiUrlKey] = normalized }
                synchronized(this@SettingsManager) {
                    if (previous != normalized) TokenHolder.clear()
                    cachedApiUrl = normalized
                }
            }
        }
    }

    suspend fun setBiometricEnabled(enabled: Boolean) {
        context.dataStore.edit { prefs -> prefs[biometricEnabledKey] = enabled }
    }

    suspend fun clearToken() {
        clearSession()
    }

    fun clearRejectedToken(rejected: String) {
        TokenHolder.clearRejected(rejected)
    }

    /**
     * Logout clears RAM, not the registered device key. Future biometric login
     * must obtain a fresh single-use challenge and a newly issued server token.
     */
    suspend fun clearSession() {
        TokenHolder.clear()
        context.dataStore.edit { prefs ->
            prefs.remove(tokenKey)
            prefs.remove(roleKey)
        }
    }
}

